CREATE TABLE IF NOT EXISTS iam.role (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(32) UNIQUE NOT NULL, identity_kind varchar(20) NOT NULL, built_in boolean NOT NULL DEFAULT true, status varchar(16) NOT NULL DEFAULT 'ACTIVE', version bigint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS iam.capability (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(100) UNIQUE NOT NULL, resource_type varchar(64) NOT NULL, action varchar(64) NOT NULL, risk_level varchar(16) NOT NULL, scope_resolver varchar(64) NOT NULL, authorization_profile varchar(20) NOT NULL, step_up_required boolean NOT NULL DEFAULT false, status varchar(16) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS iam.role_capability (role_id uuid NOT NULL REFERENCES iam.role(id) ON DELETE RESTRICT, capability_id uuid NOT NULL REFERENCES iam.capability(id) ON DELETE RESTRICT, PRIMARY KEY(role_id, capability_id));
